  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Determines whether a booking represented by the current Booking object is eligible to be accepted. It verifies the validity of the booking's customer, trip, and booking date, checks that the requested seats do not exceed the remaining seats, ensures the booking is placed strictly more than two hours before departure, and confirms that the customer does not already hold another booking whose trip time overlaps on the same day.
   * Algorithm:
   *   1. If customer is null OR trip is null OR bookingDate is null, return false.
   *   2. If numberOfSeats <= 0, return false.
   *   3. Let booked = trip.getBookedSeats(); available = trip.numberOfSeats - booked.
   *   4. If numberOfSeats > available, return false.
   *   5. Parse bookingDate and trip.departureTime as datetime strings "yyyy-MM-dd HH:mm".
   *   6. If the duration between bookingDate and trip.departureTime is not strictly greater than 2 hours, return false.
   *   7. For each existing booking b in customer.bookings:
   *        If b is not this booking and b.trip is not null, parse b.trip.departureTime and b.trip.arrivalTime and trip.departureTime and trip.arrivalTime as "yyyy-MM-dd HH:mm".
   *        If the departure date (yyyy-MM-dd) of b.trip matches the departure date of this trip,
   *        and the datetime intervals [b.trip.departureTime, b.trip.arrivalTime) and [trip.departureTime, trip.arrivalTime) overlap, return false.
   *   8. Return true.
   * Related Features: bookingDate, numberOfSeats, customer, trip
   * Related Classes: Customer, Trip
   * Input: None (operates on the implicit receiver and its attributes).
   * Output: boolean - true if the booking is eligible to be accepted; false otherwise.
   * Pre-condition: The Booking instance and the referenced Customer and Trip must have been properly initialized; bookingDate must be parseable as "yyyy-MM-dd HH:mm"; trip.departureTime and trip.arrivalTime must be parseable as "yyyy-MM-dd HH:mm" when needed.
   * Post-condition: When true is returned, all eligibility conditions are satisfied and the booking can be persisted; the actual seat reduction is performed by updateTripSeats (or by a subsequent call to Trip.bookSeats). When false is returned, no state change occurs.
   * <!-- end-model-doc -->
   * @model kind="operation"
   *        annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean isBookingEligible()
  {
    Customer cust = getCustomer();
    Trip trp = getTrip();
    Date bkDate = getBookingDate();
    int seats = getNumberOfSeats();

    // Step 1: basic null checks
    if (cust == null || trp == null || bkDate == null)
    {
      return false;
    }

    // Step 2: numberOfSeats must be positive
    if (seats <= 0)
    {
      return false;
    }

    // Step 3: compute available seats
    int booked = trp.getBookedSeats();
    int available = trp.getNumberOfSeats() - booked;

    // Step 4: requested seats must fit in remaining capacity
    if (seats > available)
    {
      return false;
    }

    SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm");
    try
    {
      // Step 5: parse booking date and trip departure time
      Date bookingParsed = sdf.parse(sdf.format(bkDate));
      Date departureParsed = sdf.parse(trp.getDepartureTime());
      Date arrivalParsed = sdf.parse(trp.getArrivalTime());

      // Step 6: booking must be placed strictly more than 2 hours before departure
      long diffMillis = departureParsed.getTime() - bookingParsed.getTime();
      long twoHoursMillis = 2L * 60L * 60L * 1000L;
      if (diffMillis <= twoHoursMillis)
      {
        return false;
      }

      // Step 7: check overlap with the customer's other bookings on the same day
      String thisDepartureDate = trp.getDepartureTime().substring(0, 10);
      for (Booking b : cust.getBookings())
      {
        if (b == this || b == null)
        {
          continue;
        }
        Trip bTrip = b.getTrip();
        if (bTrip == null)
        {
          continue;
        }

        String bDepartureStr = bTrip.getDepartureTime();
        String bArrivalStr = bTrip.getArrivalTime();
        if (bDepartureStr == null || bArrivalStr == null)
        {
          continue;
        }

        // Same-day comparison based on yyyy-MM-dd prefix
        if (bDepartureStr.length() < 10 || !bDepartureStr.substring(0, 10).equals(thisDepartureDate))
        {
          continue;
        }

        Date bDeparture = sdf.parse(bDepartureStr);
        Date bArrival = sdf.parse(bArrivalStr);

        // Interval overlap test: [bDeparture, bArrival) ∩ [departureParsed, arrivalParsed) is non-empty
        if (bDeparture.before(arrivalParsed) && departureParsed.before(bArrival))
        {
          return false;
        }
      }
    }
    catch (ParseException e)
    {
      return false;
    }

    // Step 8: all eligibility conditions satisfied
    return true;
  }

